draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // pot
  ctx.fillStyle = 'lightgray';
  ctx.fillRect(W / 2 - 50, H / 2 - 75, 100, 100);
  ctx.strokeRect(W / 2 - 50, H / 2 - 75, 100, 100);

  // vegetables
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W / 2 - 30, H / 2 - 30, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 30, H / 2 - 30, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // steaming
  ctx.fillStyle = 'lightblue';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 20, 10 + 5 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // nutrition loss
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.arc(W / 2 - 60 + 20 * Math.sin(t), H / 2 + 60, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
